<script setup>
import BreathingBalloon from './BreathingBalloon.vue';
defineProps({snapshot:Object,timing:Object,state:String,color:String,reduced:Boolean});defineEmits(['pause','resume','stop','home']);
</script>
<template><section class="exercise card" :data-elapsed-ms="snapshot.elapsedMs" :data-phase="snapshot.phase" :data-state="state" :data-entry-ms="timing?.entry" :data-first-instruction-frame-ms="timing?.firstFrame" :data-final-instruction-frame-ms="timing?.finalFrame" :data-guided-frame-duration-ms="timing?.finalFrame&&timing?.firstFrame ? timing.finalFrame-timing.firstFrame : null"><div class="section-top"><span class="eyebrow">Paced breathing</span><span class="fine">{{ state==='completed' ? '6 of 6 cycles' : `Cycle ${snapshot.cycle} of 6` }}</span></div><h2 aria-live="polite">{{state==='paused'?'Take your time.':state==='completed'?'A moment, taken.':state==='stopped'?'You can leave whenever you want.':snapshot.phase==='inhale'?'Breathe in.':'Breathe out.'}}</h2><p class="instruction">{{state==='paused'?'Your pace is paused. Resume whenever you choose.':state==='completed'?'The six cycles are complete. Stay here, or choose what comes next.':state==='stopped'?'Stopped. There is no need to finish.':snapshot.phase==='inhale'?'Gently, for four seconds.':'Gently, for six seconds.'}}</p><BreathingBalloon :inflation="snapshot.inflation" :color="color" :reduced="reduced"/><div class="pace-detail" v-if="state==='active'"><span>{{snapshot.phase==='inhale'?'Inhale':'Exhale'}}</span><strong>{{snapshot.remaining}}</strong><span>seconds</span></div><p v-else class="pace-detail">{{state==='paused'?'Paused':state==='completed'?'60-second sequence complete':'Stopped'}}</p><div class="progress-track" role="progressbar" aria-label="Breathing sequence" :aria-valuenow="Math.round(snapshot.elapsedMs/600)" aria-valuemin="0" aria-valuemax="100"><span :style="{width:`${snapshot.elapsedMs/600}%`}"></span></div><div class="exercise-controls"><button v-if="state==='active'" class="secondary" @click="$emit('pause')">Pause</button><button v-if="state==='paused'" class="primary" @click="$emit('resume')">Resume</button><button v-if="['active','paused'].includes(state)" class="text-button" @click="$emit('stop')">Stop exercise</button><button v-else class="secondary" @click="$emit('home')">Return home</button></div><p class="fine">A visual pacing cue. Breathe comfortably; you can stop at any time. {{reduced?'Reduced motion is on.':''}}</p></section></template>
